/**
 * Generated by `createservice miniapp.PublishB2BAppService`
 */

const fs = require('fs')

const dayjs = require('dayjs')
const got = require('got')
const isEqual = require('lodash/isEqual')
const pick = require('lodash/pick')

const { GQLError, GQLErrorCode: { BAD_USER_INPUT, INTERNAL_ERROR } } = require('@open-hearth/keystone/errors')
const { getLogger } = require('@open-hearth/keystone/logging')
const { GQLCustomSchema } = require('@open-hearth/keystone/schema')

const { REMOTE_SYSTEM } = require('@dev-portal-api/domains/common/constants/common')
const { productionClient, developmentClient } = require('@dev-portal-api/domains/common/utils/serverClients')
const { HearthB2BAppGql, HearthOIDCClientGql, HearthB2BAppAccessRightGql, HearthB2BAppAccessRightSetGql } = require('@dev-portal-api/domains/hearth/gql')
const access = require('@dev-portal-api/domains/miniapp/access/PublishB2BAppService')
const { B2B_APP_ACCESS_RIGHT_SET_APPROVED_STATUS } = require('@dev-portal-api/domains/miniapp/constants/b2bAppAccessRightSet')
const { APP_NOT_FOUND, FIRST_PUBLISH_WITHOUT_INFO, PUBLISH_NOT_ALLOWED, HEARTH_APP_NOT_FOUND } = require('@dev-portal-api/domains/miniapp/constants/errors')
const { B2B_APP_DEFAULT_LOGO_PATH } = require('@dev-portal-api/domains/miniapp/constants/publishing')
const { PROD_ENVIRONMENT, PUBLISH_REQUEST_APPROVED_STATUS } = require('@dev-portal-api/domains/miniapp/constants/publishing')
const { B2BApp, B2BAppPublishRequest, B2BAppAccessRightSet, B2BAppAccessRight } = require('@dev-portal-api/domains/miniapp/utils/serverSchema')
const { wrapResolverWithEnvironmentLock } = require('@dev-portal-api/domains/miniapp/utils/serverSchema/locks')

const { extractDevicePermissionsForHearth, getEnvironmentalPermissionsFieldsSelection } = require('./fields/devicePermissions')
const { getEnvironmentalFieldsSelection, getEnvironmentalFieldName } = require('./fields/environmental')
const { PERMISSION_FIELDS } = require('./fields/rightSetPermissions')
const { getOIDCClientWhere } = require('./GetOIDCClientService')

const ACCESS_RIGHT_SET_PERMISSIONS = Object.keys(PERMISSION_FIELDS)
const B2B_APP_EXPORTED_FIELDS = `id name developer developerUrl createdBy { name } logo { publicUrl originalFilename mimetype } shortDescription detailedDescription category contextDefaultStatus ${getEnvironmentalPermissionsFieldsSelection({ listKey: 'B2BApp' })} ${getEnvironmentalFieldsSelection(['exportId', 'oidcClientId', 'appUrl'])}`
const B2B_APP_ACCESS_RIGHT_SET_FIELDS = `id ${ACCESS_RIGHT_SET_PERMISSIONS.join(' ')}`

/**
 * List of possible errors, that this custom schema can throw
 * They will be rendered in documentation section in GraphiQL for this custom schema
 */
const ERRORS = {
    APP_NOT_FOUND: {
        code: BAD_USER_INPUT,
        type: APP_NOT_FOUND,
        message: 'The application with the specified ID was not found',
        messageForUser: 'api.miniapp.APP_NOT_FOUND',
    },
    FIRST_PUBLISH_WITHOUT_INFO: {
        code: BAD_USER_INPUT,
        type: FIRST_PUBLISH_WITHOUT_INFO,
        message: 'The first publication of the application should include information about the application',
        messageForUser: 'api.miniapp.publishB2BApp.FIRST_PUBLISH_WITHOUT_INFO',
    },
    PUBLISH_NOT_ALLOWED: {
        code: BAD_USER_INPUT,
        type: PUBLISH_NOT_ALLOWED,
        message: 'The application cannot be published to the specified stand, as this requires additional verification',
        messageForUser: 'api.miniapp.publishB2BApp.PUBLISH_NOT_ALLOWED',
    },
    HEARTH_APP_NOT_FOUND: {
        code: INTERNAL_ERROR,
        type: HEARTH_APP_NOT_FOUND,
        message: 'The application was probably deleted on remote server. Try to publish app info to recreate it',
        messageForUser: 'api.miniapp.publishB2BApp.HEARTH_APP_NOT_FOUND',
    },
}

const logger = getLogger()

function getExportIdField (environment) {
    return `${environment}ExportId`
}

function getAppUrlField (environment) {
    return `${environment}AppUrl`
}

async function publishAppChanges ({ app, hearthApp, serverClient, args, context }) {
    const { data: { dv, sender, environment } } = args
    logger.info({
        msg: 'started app publishing',
        entityId: app.id,
        entity: 'B2BApp',
        environment,
    })
    const exportIdField = getExportIdField(environment)
    const exportId = app[exportIdField]
    const appUrlField = getAppUrlField(environment)
    const appUrl = app[appUrlField]

    const logoPayload = app.logo ? {
        stream: got.stream(app.logo.publicUrl),
        filename: app.logo.originalFilename,
        mimetype: app.logo.mimetype,
        modelName: 'B2BApp',
    } : {
        stream: fs.createReadStream(B2B_APP_DEFAULT_LOGO_PATH),
        filename: 'default-logo.png',
        mimetype: 'image/png',
        modelName: 'B2BApp',
    }

    const logo = await serverClient.uploadFile(logoPayload)

    // Step 1. Prepare payload
    const appPayload = {
        ...extractDevicePermissionsForHearth(app, environment),
        dv,
        sender,
        name: app.name,
        logo,
        developer: app.developer || app.createdBy.name,
        developerUrl: app.developerUrl,
        shortDescription: app.shortDescription,
        detailedDescription: app.detailedDescription,
        category: app.category,
        appUrl,
        contextDefaultStatus: app.contextDefaultStatus,
        importId: app.id,
        importRemoteSystem: REMOTE_SYSTEM,
    }

    // Step 2. Update / create app in hearth
    let updatedHearthApp
    if (hearthApp) {
        // App found -> update
        logger.info({
            msg: 'found existing hearth app',
            entityId: app.id,
            entity: 'B2BApp',
            environment,
            data: { hearthAppId: hearthApp.id },
        })
        updatedHearthApp = await serverClient.updateModel({
            modelGql: HearthB2BAppGql,
            id: hearthApp.id,
            updateInput: appPayload,
        })
        logger.info({
            msg: 'hearth app successfully updated',
            entityId: app.id,
            entity: 'B2BApp',
            data: { hearthAppId: hearthApp.id },
            environment,
        })
    } else {
        // App not found -> create new one
        // NOTE: initial publish must be done with isHidden flag set to true,
        // so it can be tested on production before showing to users
        appPayload.isHidden = environment === PROD_ENVIRONMENT

        logger.info({
            msg: 'hearth app not found. Creating new one',
            entityId: app.id,
            entity: 'B2BApp',
            environment,
        })
        updatedHearthApp = await serverClient.createModel({
            modelGql: HearthB2BAppGql,
            createInput: appPayload,
        })
        logger.info({
            msg: 'hearth app successfully created',
            entityId: app.id,
            entity: 'B2BApp',
            environment,
            data: { hearthAppId: updatedHearthApp.id },
        })
    }

    // Update exportIdField if needed
    if (!exportId || exportId !== updatedHearthApp.id) {
        await B2BApp.update(context, app.id, {
            dv,
            sender,
            [exportIdField]: updatedHearthApp.id,
        })
        logger.info({
            msg: 'dev-portal app exportId updated',
            entityId: app.id,
            entity: 'B2BApp',
            environment,
            data: { hearthAppId: updatedHearthApp.id },
        })
    }

    return updatedHearthApp
}

async function syncOIDCClient ({ args, serverClient, hearthApp, localApp }) {
    const { data: { dv, sender, app, environment } } = args

    const oidcClientIdField = `${environment}OidcClientId`
    const explicitId = localApp[oidcClientIdField]

    const orClauses = []
    if (explicitId) orClauses.push({ AND: [{ id: explicitId }] })
    orClauses.push({ AND: [getOIDCClientWhere(app)] })

    const oidcClients = await serverClient.getModels({
        modelGql: HearthOIDCClientGql,
        where: { OR: orClauses },
        first: 2,
    })
    const preferred = explicitId && oidcClients.find(c => c.id === explicitId)
    const oidcClient = preferred || oidcClients[0] || null

    if (!oidcClient) {
        logger.info({
            msg: 'no OIDC clients found for app',
            entityId: app.id,
            entity: 'B2BApp',
            environment,
        })
        return
    }

    if (!oidcClient.isEnabled) {
        await serverClient.updateModel({
            modelGql: HearthOIDCClientGql,
            id: oidcClient.id,
            updateInput: {
                dv,
                sender,
                isEnabled: true,
            },
        })
        logger.info({
            msg: 'OIDC client is enabled now',
            entityId: app.id,
            entity: 'B2BApp',
            environment,
            data: { oidcClientId: oidcClient.id },
        })
    }

    if (hearthApp.oidcClient?.id !== oidcClient.id) {
        await serverClient.updateModel({
            modelGql: HearthB2BAppGql,
            id: hearthApp.id,
            updateInput: {
                dv,
                sender,
                oidcClient: { connect: { id: oidcClient.id } },
            },
        })
        logger.info({
            msg: 'B2BApp is connected to OIDC client',
            entityId: app.id,
            entity: 'B2BApp',
            environment,
            data: { oidcClientId: oidcClient.id },
        })
    }
}

async function addAccessRight ({ args, context, serverClient, hearthApp }) {
    const { data: { dv, sender, app: { id }, environment } } = args
    const exportField = `${environment}ExportId`
    const accessRight = await B2BAppAccessRight.getOne(context, {
        app: { id },
        environment,
        deletedAt: null,
    }, 'id hearthUserId')

    if (accessRight) {
        logger.info({
            msg: 'access right found for app',
            entityId: id,
            entity: 'B2BApp',
            environment,
            data: { accessRightId: accessRight.id },
        })
    } else {
        logger.info({
            msg: 'access right not found for app',
            entityId: id,
            entity: 'B2BApp',
            environment,
        })
    }

    let hearthRight

    const hearthRights = await serverClient.getModels({
        modelGql: HearthB2BAppAccessRightGql,
        where: {
            app: { id: hearthApp.id },
        },
        first: 1,
    })

    if (hearthRights.length) {
        hearthRight = hearthRights[0]
        logger.info({
            msg: 'existing hearth access right found for app',
            entityId: id,
            entity: 'B2BApp',
            environment,
            data: { accessRightId: accessRight?.id, hearthAccessRightId: hearthRight.id },
        })
    }

    if (hearthRight) {
        const hearthUserId = hearthRight.user?.id
        if (!accessRight || hearthUserId !== accessRight.hearthUserId) {
            const stateMsg = !accessRight
                ? 'existing hearth access right does not match dev-portal one'
                : 'existing hearth access right user does not match with dev-portal one'
            logger.info({
                msg: stateMsg,
                entityId: id,
                entity: 'B2BApp',
                environment,
                data: { accessRightId: accessRight?.id, hearthAccessRightId: hearthRight.id  },
            })
            await serverClient.updateModel({
                modelGql: HearthB2BAppAccessRightGql,
                id: hearthRight.id,
                updateInput: {
                    dv,
                    sender,
                    deletedAt: dayjs().toISOString(),
                },
            })
            logger.info({
                msg: 'existing hearth access right successfully deleted',
                entityId: id,
                entity: 'B2BApp',
                environment,
                data: { accessRightId: accessRight?.id, hearthAccessRightId: hearthRight.id  },
            })
            hearthRight = null
        }
    }

    if (!accessRight) {
        return
    }

    if (!hearthRight) {
        logger.info({
            msg: 'creating new hearth access right',
            entityId: id,
            entity: 'B2BApp',
            environment,
            data: { accessRightId: accessRight.id },
        })
        hearthRight = await serverClient.createModel({
            modelGql: HearthB2BAppAccessRightGql,
            createInput: {
                dv,
                sender,
                app: { connect: { id: hearthApp.id } },
                user: { connect: { id: accessRight.hearthUserId } },
                importId: accessRight.id,
                importRemoteSystem: REMOTE_SYSTEM,
            },
        })
        logger.info({
            msg: 'Updating dev-portal access right info',
            entityId: id,
            entity: 'B2BApp',
            environment,
            data: { accessRightId: accessRight.id, hearthAccessRightId: hearthRight.id },
        })
        await B2BAppAccessRight.update(context, accessRight.id, {
            dv,
            sender,
            [exportField]: hearthRight.id,
        })
    }

    const accessRightSet = await B2BAppAccessRightSet.getOne(context, {
        app: { id },
        environment,
        status: B2B_APP_ACCESS_RIGHT_SET_APPROVED_STATUS,
        deletedAt: null,
    }, B2B_APP_ACCESS_RIGHT_SET_FIELDS)

    if (!accessRightSet && hearthRight?.accessRightSet) {
        logger.info({
            msg: 'Deleting hearth B2BAppAccessRightSet',
            entityId: id,
            entity: 'B2BApp',
            environment,
            data: { hearthAccessRightSetId: hearthRight.accessRightSet.id },
        })

        await serverClient.updateModel({
            modelGql: HearthB2BAppAccessRightSetGql,
            id: hearthRight.accessRightSet.id,
            updateInput: {
                dv,
                sender,
                deletedAt: dayjs().toISOString(),
            },
        })
    }

    if (!accessRightSet) {
        return
    }

    const currentPermissions = pick(accessRightSet, ACCESS_RIGHT_SET_PERMISSIONS)

    if (!hearthRight?.accessRightSet) {
        logger.info({
            msg: 'Creating hearth B2BAppAccessRightSet',
            entityId: id,
            entity: 'B2BApp',
            environment,
            data: { accessRightSetId: accessRightSet.id },
        })

        hearthRight = await serverClient.updateModel({
            modelGql: HearthB2BAppAccessRightGql,
            id: hearthRight.id,
            updateInput: {
                dv,
                sender,
                accessRightSet: {
                    create: {
                        dv,
                        sender,
                        app: { connect: { id: hearthApp.id } },
                        importId: accessRightSet.id,
                        importRemoteSystem: REMOTE_SYSTEM,
                        ...currentPermissions,
                    },
                },
            },
        })
    } else if (!isEqual(currentPermissions, pick(hearthRight.accessRightSet, ACCESS_RIGHT_SET_PERMISSIONS))) {
        logger.info({
            msg: 'Updating B2BAppAccessRightSet permissions',
            entityId: id,
            entity: 'B2BApp',
            environment,
            data: { accessRightSetId: accessRightSet.id, hearthAccessRightSetId: hearthRight.accessRightSet.id },
        })
        await serverClient.updateModel({
            modelGql: HearthB2BAppAccessRightSetGql,
            id: hearthRight.accessRightSet.id,
            updateInput: {
                dv,
                sender,
                ...currentPermissions,
                importId: accessRightSet.id,
                importRemoteSystem: REMOTE_SYSTEM,
            },
        })
    }
}

const PublishB2BAppService = new GQLCustomSchema('PublishB2BAppService', {
    types: [
        {
            access: true,
            type: 'input B2BAppPublishOptions { info: Boolean }',
        },
        {
            access: true,
            type: 'input PublishB2BAppInput { dv: Int!, sender: SenderFieldInput!, app: B2BAppWhereUniqueInput!, environment: AppEnvironment!, options: B2BAppPublishOptions! }',
        },
        {
            access: true,
            type: 'type PublishB2BAppOutput { success: Boolean! }',
        },
    ],
    
    mutations: [
        {
            access: access.canPublishB2BApp,
            schema: 'publishB2BApp(data: PublishB2BAppInput!): PublishB2BAppOutput',
            resolver: wrapResolverWithEnvironmentLock(async (parent, args, context) => {
                const { data: { app: { id }, options, environment, dv, sender } } = args

                const publishingTime = dayjs().toISOString()
                const publishingField = getEnvironmentalFieldName(environment, 'publishedAt')

                const app = await B2BApp.getOne(
                    context,
                    { id, deletedAt: null },
                    B2B_APP_EXPORTED_FIELDS
                )

                if (!app) {
                    throw new GQLError(ERRORS.APP_NOT_FOUND, context)
                }

                const exportIdField = getExportIdField(environment)
                let exportId = app[exportIdField]

                if (!exportId && !options.info) {
                    throw new GQLError(ERRORS.FIRST_PUBLISH_WITHOUT_INFO, context)
                }

                if (environment === PROD_ENVIRONMENT) {
                    const publishRequest = await B2BAppPublishRequest.getOne(context, {
                        app: { id: app.id },
                        deletedAt: null,
                        status: PUBLISH_REQUEST_APPROVED_STATUS,
                    })
                    if (!publishRequest) {
                        throw new GQLError(ERRORS.PUBLISH_NOT_ALLOWED, context)
                    }
                }

                const serverClient = environment === PROD_ENVIRONMENT
                    ? productionClient
                    : developmentClient

                let hearthApp = await serverClient.findExportedModel({
                    modelGql: HearthB2BAppGql,
                    exportId,
                    id: app.id,
                    context,
                })

                if (options.info) {
                    hearthApp = await publishAppChanges({
                        app,
                        hearthApp,
                        serverClient,
                        args,
                        context,
                    })
                }

                if (!hearthApp) {
                    throw new GQLError(ERRORS.HEARTH_APP_NOT_FOUND, context)
                }

                // Step 3. Create accessRight is necessary
                await addAccessRight({ args, serverClient, context, hearthApp })

                // Step 4. If OIDC client was created, publish must enable it for usage
                await syncOIDCClient({ args, serverClient, hearthApp, localApp: app })

                await B2BApp.update(context, app.id, {
                    dv,
                    sender,
                    [publishingField]: publishingTime,
                })

                return {
                    success: true,
                }
            }),
        },
    ],
    
})

module.exports = {
    PublishB2BAppService,
}
